            start = s + 1
        if start < size:
            segments.append((start, size))
        return segments

    row_segments = get_segments(h, sep_rows)
    col_segments = get_segments(w, sep_cols)

    markers = {}
    for ri, (r0, r1) in enumerate(row_segments):
        for ci, (c0, c1) in enumerate(col_segments):
